from fixture import boot
from model import DATA
from playwright.async_api import async_playwright,expect
from pathlib import Path
import asyncio,json,copy
H=Path(__file__).parent;RESULTS=[]
async def release(p,f,kind):
 response=asyncio.create_task(p.wait_for_event('response',predicate=lambda r:r.url.endswith('/'+kind)));await asyncio.sleep(0);p.gates[kind].set();await (await response).body();await f.locator('body').evaluate('()=>new Promise(requestAnimationFrame)')
async def check(browser,engine,width):
 p,f=await boot(browser,width);groups=[];await f.locator('#filter-stream').select_option('demo-autumn');p.model.statsValues={'pending':7,'paid':4};p.gates['stats']=asyncio.Event();await f.locator('[data-view="stats"]').click();await p.started['stats'].wait();await expect(f.locator('#content')).to_be_empty();await expect(f.locator('#content')).to_have_attribute('aria-busy','true');await expect(f.locator('#notice')).to_have_text('Загружаем…');await release(p,f,'stats');await expect(f.locator('.metric').first.locator('strong')).to_have_text('7');await expect(f.locator('#content')).to_have_attribute('aria-busy','false');groups.append('pending indicators show no previous people or false zero counts')
 p.model.auditRows=[{'createdAt':'2026-10-22T08:00:00Z','targetName':'<b>Учебная участница</b>','actorName':'Учебный владелец','after':{'status':'approved','role':'PARTICIPANT','enrollment':{'streamId':'demo-autumn','basis':'cash'}}}];p.gates['audit']=asyncio.Event();await f.locator('[data-view="audit"]').click();await p.started['audit'].wait();await expect(f.locator('.metrics')).to_have_count(0);await release(p,f,'audit');await expect(f.locator('.audit')).to_contain_text('оплачено наличными · подтверждено вручную');await expect(f.locator('.audit')).to_contain_text('<b>Учебная участница</b>');await expect(f.locator('.audit b')).to_have_count(0);groups.append('history loads independently and preserves escaped names and cash meaning')
 await f.locator('[data-view="streams"]').click();await expect(f.locator('[data-stream]')).to_have_count(1);p.model.streams.append({'id':'demo-new','name':'Новый учебный поток','startDate':'2026-11-15','endDate':'2026-12-15','isActive':True});await f.locator('#refresh').click();await expect(f.locator('[data-stream]')).to_have_count(2);await expect(f.locator('#filter-stream option')).to_have_count(3);await expect(f.locator('#filter-stream')).to_have_value('demo-autumn');assert len([c for c in p.model.calls if c['path']=='/access-admin/streams'])==3;groups.append('stream refresh reads current list and preserves available selected stream')
 p.model.people[0]['enrollments']=[{'streamId':'demo-autumn','status':'active','paidAt':None,'accessBasis':'free','stream':{'name':'Учебный осенний поток'}}];await f.locator('[data-stream="demo-autumn"]').click();await expect(f.locator('[data-view="people"]')).to_have_attribute('aria-current','true');await expect(f.locator('[data-person]')).to_have_count(1);await expect(f.locator('#filter-stream')).to_have_value('demo-autumn');groups.append('stream-to-people transition keeps correct cohort scope')
 assert not[c for c in p.model.calls if c['method']!='GET'];assert await f.locator('body').evaluate('()=>document.documentElement.scrollWidth<=innerWidth');assert not p.errors,p.errors;groups.append('read-only workflow has no mutations, script errors or horizontal overflow');RESULTS.append({'engine':engine,'width':width,'groups':groups,'realWrites':0});print(engine,width,'PASS',len(groups),flush=True);await p.close()
def record(engine,name):RESULTS.append({'engine':engine,'check':name,'passed':True,'realWrites':0})
async def edges(browser,engine):
 p,f=await boot(browser,streams=[]);await f.locator('[data-view="streams"]').click();await expect(f.locator('#content')).to_have_text('Потоков пока нет.');p.model.streams=copy.deepcopy(DATA['streams']);await f.locator('#refresh').click();await expect(f.locator('[data-stream]')).to_have_count(1);record(engine,'genuine empty streams are explained and refresh can reveal a new stream');await p.close()
 p,f=await boot(browser);await f.locator('[data-view="audit"]').click();await expect(f.locator('#content')).to_contain_text('Новых решений ещё нет.');await f.locator('[data-view="stats"]').click();await expect(f.locator('.metric')).to_have_count(9);assert await f.locator('.metric strong').all_text_contents()==['0']*9;record(engine,'empty history and actual zero indicators retain correct existing meaning');await p.close()
 for view,endpoint in [('streams','streams'),('audit','audit'),('stats','stats')]:
  p,f=await boot(browser);p.model.fail['/access-admin/'+endpoint]=503;await f.locator('[data-view="'+view+'"]').click();await expect(f.locator('#content')).to_contain_text('Не удалось загрузить раздел.');assert 'Потоков пока нет'not in await f.locator('#content').text_content();await expect(f.locator('#content')).to_have_attribute('aria-busy','false');p.model.fail.clear();await f.locator('#refresh').click();await expect(f.locator('#notice')).to_have_text('');record(engine,view+' failure is distinct from empty data and explicit retry succeeds');await p.close()
 p,f=await boot(browser);p.gates['streams']=asyncio.Event();p.started['streams'].clear();await f.locator('[data-view="streams"]').click();await p.started['streams'].wait();await f.locator('[data-view="stats"]').click();await expect(f.locator('.metrics')).to_be_visible();p.model.streams.append({'id':'late','name':'Поздний учебный поток','startDate':'2026-11-01','endDate':'2026-12-01','isActive':True});await release(p,f,'streams');await expect(f.locator('.metrics')).to_be_visible();assert await f.locator('body').evaluate('()=>streams.length')==1;record(engine,'late stream read cannot overwrite indicators or shared filter choices');await p.close()
 p,f=await boot(browser);p.model.denied=True;await f.locator('[data-view="stats"]').click();await expect(f.locator('#workspace')).to_be_hidden();await expect(f.locator('[data-person]')).to_have_count(0);await expect(f.locator('#notice')).to_contain_text('отозван');record(engine,'access revocation hides loaded private data');await p.close()
async def main():
 async with async_playwright()as pw:
  for engine,widths in [('chromium',[320,390,1440]),('webkit',[390])]:
   b=await getattr(pw,engine).launch()
   for width in widths:await check(b,engine,width)
   await edges(b,engine);await b.close()
 (H/'checks.json').write_text(json.dumps(RESULTS,ensure_ascii=False,indent=2),encoding='utf-8')
asyncio.run(main())
